import os
import torch
import numpy as np
import random


class Config:
    """
    Configuration class for the Glioblastoma MGMT Promoter Methylation Prediction Task.
    Implements parameters for the Stochastic 2.5D Volumetric Ensemble strategy.
    """

    # ==========================================
    # Directories & File Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_4"

    # Metadata files generated by the metadata script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Submission paths
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Preprocessing & Augmentation
    # ==========================================
    IMG_SIZE = 224
    NUM_CHANNELS = 3  # FLAIR, T1wCE, T2w

    # Volume of Interest (VOI) Strategy
    # Using deterministic middle slice selection (Cite solution_lesson_node_00015)

    # Debugging / Development
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 50  # Subset size for rapid debugging

    # ==========================================
    # Model Architecture
    # ==========================================
    MODEL_NAME = "efficientnet_b0"
    PRETRAINED = True
    NUM_CLASSES = 1
    DROPOUT_RATE = 0.2  # Standard for EfficientNet

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 32
    NUM_EPOCHS = 10
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2  # Stronger regularization as per strategy

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 3

    # ==========================================
    # Hardware & System
    # ==========================================
    SEED = 42
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @staticmethod
    def set_seed(seed=42):
        """
        Sets the random seed for reproducibility across Python, NumPy, and PyTorch.
        """
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        # Ensure deterministic behavior in CuDNN
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
        os.environ["PYTHONHASHSEED"] = str(seed)

    @staticmethod
    def setup():
        """
        Initializes the environment: creates directories and sets seeds.
        """
        # Create working directory for caching intermediate files
        os.makedirs(Config.WORKING_DIR, exist_ok=True)

        # Create submission directory
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)

        # Set reproducibility seed
        Config.set_seed(Config.SEED)
